(177379, 10009, 4388, '<td valign="top">the roundness of the hands, the roundness of the truffles, and the tonal qualities. great image! 10 goodtempo<br/></td>', 'the roundness of the hands, the roundness of the truffles, and the tonal qualities. great image! 10 goodtempo', '2002-12-23 23:29:55.000000', NULL, 1),
