(179108, 9827, 3585, '<td valign="top">Why the blue saturation? looses all organic feeling shown this way.</td>', 'Why the blue saturation? looses all organic feeling shown this way.', '2002-12-29 08:36:40.000000', NULL, 1),
(179110, 10007, 3585, '<td valign="top">The apple is at the same time the center of interest and a bit of a symbolic overkill in this image. I guess it is a well-shared concept to situate the center of sin and virtue, good and evil, at this area of the body even that we all know it is found only much higher. A bunch of dark grapes, symbol of festive pleasures would have been graphically very interesting, would fit perfectly and naturally between these hands.  Good image nevertheless, nice skin tones and overall effect. Maybe a little more space at the bottom for these fingers to end.  9</td>', 'The apple is at the same time the center of interest and a bit of a symbolic overkill in this image. I guess it is a well-shared concept to situate the center of sin and virtue, good and evil, at this area of the body even that we all know it is found only much higher. A bunch of dark grapes, symbol of festive pleasures would have been graphically very interesting, would fit perfectly and naturally between these hands.  Good image nevertheless, nice skin tones and overall effect. Maybe a little more space at the bottom for these fingers to end.  9', '2002-12-29 09:04:18.000000', NULL, 1),
(179118, 10062, 3540, '<td valign="top">The colors really make this picture, mostly because the pink and yellow are so not natural human colors, but the effect used to make them so is so simple.  Nice concept and great picture - Inspzil</td>', 'The colors really make this picture, mostly because the pink and yellow are so not natural human colors, but the effect used to make them so is so simple.  Nice concept and great picture - Inspzil', '2002-12-29 09:34:17.000000', NULL, 1),
