(179365, 9982, 3280, '<td valign="top">My favorite!  Great shot.  Congrats and keep up the good work!</td>', 'My favorite!  Great shot.  Congrats and keep up the good work!', '2002-12-30 00:09:22.000000', NULL, 0),
